	}
	o.Status = status
	st.items[id] = o
	return o, true
}

// List returns all orders sorted by ID.
func (st *OrderStore) List() []Order {
	st.mu.RLock()
	defer st.mu.RUnlock()
	out := make([]Order, 0, len(st.items))
	for _, o := range st.items {
		out = append(out, o)
	}
	slices.SortFunc(out, func(a, b Order) int { return strings.Compare(a.ID, b.ID) })
	return out
