		}
		if it.Quantity < 1 {
			return validationError{fmt.Sprintf("items[%d].quantity", i), "must be at least 1"}
		}
	}
	return nil
}

func (s *Server) handleListOrders(w http.ResponseWriter, r *http.Request) {
